  rel:=pg_catalog.to_regclass('naijue_erp.'||(t->>'name'));
  IF rel IS NULL OR rel::oid::text<>t->>'oid'
   OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid=rel AND pg_catalog.pg_get_userbyid(c.relowner)='erp_rewrite_owner_20261022'
    AND c.relacl::text=t->>'tableAcl' AND NOT c.relrowsecurity AND NOT c.relforcerowsecurity)
  THEN RAISE EXCEPTION 'Original relation identity/table ACL/RLS changed'; END IF;
  SELECT jsonb_agg(a.attname::text ORDER BY a.attnum) INTO names FROM pg_catalog.pg_attribute a WHERE a.attrelid=rel AND a.attnum>0 AND NOT a.attisdropped;
  IF names IS DISTINCT FROM (SELECT jsonb_agg(c->'name' ORDER BY n) FROM jsonb_array_elements(t->'columns') WITH ORDINALITY z(c,n))
  THEN RAISE EXCEPTION 'Original complete physical column set changed'; END IF;
  FOR col IN SELECT value FROM jsonb_array_elements(t->'columns') LOOP
   IF (SELECT a.attacl::text FROM pg_catalog.pg_attribute a WHERE a.attrelid=rel AND a.attname=col->>'name') IS DISTINCT FROM col->>'rawAcl' THEN RAISE EXCEPTION '197 raw column ACL prestate changed'; END IF;
   SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN q.grantee=0 THEN '' ELSE pg_catalog.pg_get_userbyid(q.grantee) END,
    'grantor',pg_catalog.pg_get_userbyid(q.grantor),'privilege',q.privilege_type,'grantable',q.is_grantable)
    ORDER BY CASE WHEN q.grantee=0 THEN '' ELSE pg_catalog.pg_get_userbyid(q.grantee) END,pg_catalog.pg_get_userbyid(q.grantor),q.privilege_type,q.is_grantable),'[]'::jsonb)
   INTO actual FROM pg_catalog.pg_attribute a CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(a.attacl,'{}'::aclitem[])) q
   WHERE a.attrelid=rel AND a.attname=col->>'name' AND a.attnum>0 AND NOT a.attisdropped;
   IF actual IS DISTINCT FROM col->'before' THEN RAISE EXCEPTION 'Unexpected column ACL bit, grantor or grant option'; END IF;
  END LOOP;
 END LOOP;
END $state$;
